// Package postgresql turns PostgreSQL on for an application generated by
// Clarity: importing it is enough.
//
//	import _ "github.com/petervdpas/Clarity/runtimes/go/postgresql"
//
// Through pgx: decimals are NUMERIC, dates DATE and TIMESTAMP, bools
// BOOLEAN. pgx reads the location as the project file writes it, a URL or
// libpq's key=value words. A migration step runs in one transaction, so a
// step that fails leaves the database as it was.
package postgresql

import (
	"database/sql"
	"errors"

	"github.com/jackc/pgx/v5/pgconn"
	"github.com/petervdpas/Clarity/runtimes/go/clarity"
	// The driver registers itself as "pgx".
	_ "github.com/jackc/pgx/v5/stdlib"
)

// foreignKey is foreign_key_violation.
const foreignKey = "23503"

func init() { clarity.UseServer(clarity.Postgres, open) }

func open(location string) (clarity.Server, error) {
	db, err := sql.Open("pgx", location)
	if err != nil {
		return clarity.Server{}, err
	}
	isReference := func(err error) bool {
		var e *pgconn.PgError
		return errors.As(err, &e) && e.Code == foreignKey
	}
	return clarity.Server{DB: db, IsReference: isReference, Value: clarity.AsTime, Returning: true, Undoes: true}, nil
}
